///|
/// Arguments retain their syntactic role until ordinary Program lowering.
/// A producer name is never inferred from the content of a string literal.
pub(all) enum SgaArgument {
  Producer(NamePart)
  FieldReference(Array[NamePart])
  TextValue(String)
  NumberValue(String)
  BooleanValue(Bool)
  NullValue
  ParameterValue(String)
  ObjectValue(Array[(String, SgaArgument)])
  ListValue(Array[SgaArgument])
} derive(Eq, Debug)

///|
pub(all) struct SgaCall {
  operation : String
  arguments : Array[(String, SgaArgument)]
  start : Int
  end : Int
} derive(Eq, Debug)

///|
// These are the adopted ActQL logical operation names, not GQL functions or
// provider procedures. No backend, acquisition or materialization is chosen.
fn sga_operation(name : String) -> Bool {
  match name {
    "to_vectors"
    | "normalize_vectors"
    | "score_vectors"
    | "vectors"
    | "to_events"
    | "session"
    | "events"
    | "reach"
    | "traverse"
    | "shortest_path"
    | "components"
    | "degree"
    | "graph_bounds"
    | "match_nodes"
    | "match_edges"
    | "normalize_graph"
    | "subgraph"
    | "graft_graph"
    | "union_graphs"
    | "subtract_graphs"
    | "graphs_equal"
    | "graph_diff"
    | "apply_graph_delta"
    | "mean_graphs"
    | "node_rows"
    | "edge_rows" => true
    _ => false
  }
}

///|
// Currently connected source lowerings with Relation output. False does not
// assert a Graph output: other logical operations can remain unsupported.
// The common checker owns Carrier validity and the operation's output schema.
pub fn has_sga_relation_lowering(operation : String) -> Bool {
  match operation {
    "node_rows"
    | "edge_rows"
    | "degree"
    | "graph_bounds"
    | "components"
    | "graphs_equal"
    | "graph_diff"
    | "match_nodes"
    | "match_edges"
    | "traverse"
    | "reach"
    | "shortest_path" => true
    _ => false
  }
}

///|
fn sga_call_head(token : Token) -> Bool {
  match token.value {
    Word(name) => sga_operation(ascii_upper(name).to_lower())
    _ => false
  }
}

///|
fn copy_sga_argument(argument : SgaArgument) -> SgaArgument {
  match argument {
    ObjectValue(fields) =>
      ObjectValue(fields.map(field => (field.0, copy_sga_argument(field.1))))
    ListValue(items) => ListValue(items.map(copy_sga_argument))
    other => other
  }
}

///|
fn copy_sga_call(call : SgaCall) -> SgaCall {
  {
    ..call,
    arguments: call.arguments.map(field => (field.0, copy_sga_argument(field.1))),
  }
}

///|
/// Consume a lowered Graph prefix exactly once. Relational compilation cannot
/// silently ignore a Graph call; the caller must first emit every prefix step.
pub fn after_graph_calls(query : Query) -> Query {
  let mut count = 0
  while count < query.operations.length() &&
        query.operations[count] is GraphCall(_) {
    count += 1
  }
  { ..query, operations: query.operations[count:].to_owned(), }
}

///|
// A role comes from the existing logical operation contract. For example,
// reach.start.from is a Relation producer, while reach.start is an ID value.
fn sga_producer_argument(operation : String, path : Array[String]) -> Bool {
  match operation {
    "reach" | "traverse" => path == ["start", "from"]
    "shortest_path" => path == ["source", "from"] || path == ["target", "from"]
    "subgraph" => path == ["nodes", "from"]
    "graphs_equal"
    | "graph_diff"
    | "graft_graph"
    | "union_graphs"
    | "subtract_graphs"
    | "apply_graph_delta"
    | "mean_graphs" => path == ["with"]
    _ => false
  }
}

///|
fn sga_selector_object(operation : String, path : Array[String]) -> Bool {
  match operation {
    "reach" => path == ["start"]
    "traverse" => path == ["start"] || path == ["hops"]
    "shortest_path" => path == ["source"] || path == ["target"]
    "subgraph" => path == ["nodes"]
    "union_graphs" | "subtract_graphs" => path == ["merge"]
    "match_nodes" | "match_edges" => path == ["bindings"]
    _ => false
  }
}

///|
fn QueryParser::sga_argument(
  self : QueryParser,
  operation : String,
  path : Array[String],
  depth : Int,
) -> SgaArgument raise QueryAbort {
  // Keep recursion bounded independently of the caller's configurable budget.
  // Work and syntax nodes are charged to the containing query parser.
  if depth > self.limits.expression.max_depth || depth > 32 {
    raise QueryAbort("SGA argument depth limit", self.peek().start)
  }
  self.node()
  let token = self.peek()
  if token.value == Symbol(91) {
    self.symbol(91)
    let items : Array[SgaArgument] = []
    while self.peek().value != Symbol(93) {
      items.push(self.sga_argument(operation, path, depth + 1))
      if self.peek().value != Symbol(44) {
        break
      }
      self.symbol(44)
      if self.peek().value == Symbol(93) {
        raise QueryAbort("Expected SGA list member", self.peek().start)
      }
    }
    self.symbol(93)
    return ListValue(items)
  }
  if path.length() == 1 &&
    (
      (operation == "to_vectors" && ["id", "vector"].contains(path[0])) ||
      (operation == "to_events" && ["id", "time"].contains(path[0])) ||
      (operation == "session" && ["id", "time", "by"].contains(path[0]))
    ) {
    return FieldReference(self.path())
  }
  if sga_producer_argument(operation, path) {
    // Bare and backtick names are references. A quoted STRING is a value,
    // and cannot select an existing producer, including inside explicit lists.
    return Producer(self.resolve_producer([self.name()])[0])
  }
  if token.value == Symbol(123) {
    self.symbol(123)
    let fields = self.sga_arguments(operation, path, depth + 1, 125)
    self.symbol(125)
    return ObjectValue(fields)
  }
  match self.advance().value {
    Text(value) => {
      let output = StringBuilder()
      output.write_string(value)
      // Keep the existing GoogleSQL lexical rule for adjacent String chunks.
      // Each decoded chunk retains its value; this is not NFC/LF conversion.
      while self.peek().value is Text(chunk) {
        ignore(self.advance())
        output.write_string(chunk)
      }
      TextValue(output.to_string())
    }
    Numeric(value) => NumberValue(value)
    Parameter(name) => ParameterValue(self.source.identifier(name))
    Word(name) if ascii_upper(name) == "TRUE" => BooleanValue(true)
    Word(name) if ascii_upper(name) == "FALSE" => BooleanValue(false)
    Word(name) if ascii_upper(name) == "NULL" => NullValue
    Symbol(45) => {
      let number = self.advance()
      match number.value {
        Numeric(value) => NumberValue("-" + value)
        _ => raise QueryAbort("Expected SGA numeric value", number.start)
      }
    }
    _ =>
      raise QueryAbort("Expected SGA value or producer reference", token.start)
  }
}

///|
fn QueryParser::sga_arguments(
  self : QueryParser,
  operation : String,
  path : Array[String],
  depth : Int,
  closing : Int,
) -> Array[(String, SgaArgument)] raise QueryAbort {
  let fields : Array[(String, SgaArgument)] = []
  while self.peek().value != Symbol(closing) {
    self.node()
    let at = self.peek().start
    let name = self.name()
    // Fold typed argument vocabulary only. Object-valued data (for
    // example a predicate's literal object) retains its authored field names.
    // Folding every nested String key would change a value before admission.
    let key = if path.is_empty() || sga_selector_object(operation, path) {
      ascii_upper(name.value).to_lower()
    } else {
      name.value
    }
    self.spend(fields.length())
    if fields.any(field => field.0 == key) {
      raise QueryAbort("Duplicate SGA argument", at)
    }
    self.symbol(58)
    let value = self.sga_argument(operation, path + [key], depth)
    fields.push((key, value))
    if self.peek().value != Symbol(44) {
      break
    }
    self.symbol(44)
    if self.peek().value == Symbol(closing) {
      raise QueryAbort("Expected SGA named argument", self.peek().start)
    }
  }
  fields
}

///|
fn QueryParser::sga_call(self : QueryParser) -> SgaCall raise QueryAbort {
  self.node()
  let token = self.advance()
  let operation = match token.value {
    Word(name) => ascii_upper(name).to_lower()
    _ => raise QueryAbort("Expected SGA operation name", token.start)
  }
  if !sga_operation(operation) {
    raise QueryAbort("Unknown SGA operation", token.start)
  }
  self.symbol(40)
  let arguments = self.sga_arguments(operation, [], 1, 41)
  let end = self.peek().end
  self.symbol(41)
  { operation, arguments, start: token.start, end, }
}

///|
/// Parse one adopted named call using the same bounded token and query parser.
/// This syntax entry does not admit a Program or authorize/execute a provider.
/// Public script lowering and common consumer support are separate obligations.
pub fn parse_sga_call(
  text : String,
  limits : QueryLimits,
  source_path? : String = "<query>",
) -> Result[SgaCall, Diagnostic] {
  if [limits.max_syntax_nodes, limits.max_work, limits.expression.max_depth].any(n => {
        n < 0 || n == 2147483647
      },
    ) {
    return Err({ issue: InvalidLimits, span: None, })
  }
  let source = match tokenize(text, limits.lexical, source_path~) {
    Ok(source) => source
    Err(error) => return Err(error)
  }
  let parser : QueryParser = {
    source,
    limits,
    index: 0,
    work: 0,
    expression_nodes: 0,
    syntax_nodes: 0,
    source_depth: 0,
    synthetic_sources: 0,
    binding_scopes: [],
  }
  try {
    let call = parser.sga_call()
    if parser.peek().value != End {
      raise QueryAbort("Expected end of SGA call", parser.peek().start)
    }
    Ok(call)
  } catch {
    QueryExpression(error) => Err(error)
    QueryAbort(message, at) =>
      Err({
        issue: Syntax(message),
        span: Some(
          @origin.span(@origin.range(source.document, at, at).unwrap()),
        ),
      })
  }
}

///|
// Lower only syntax roles. Membership, predicates, path mode, hop bounds,
// typed identities, output schema and resource evidence belong to the common
// traversal checker and owner. A WITH selector reuses its emitted producer.
fn script_traversal_argument(
  construction : Construction,
  argument : @query.SgaArgument,
  known : Array[Input],
  limits : Limits,
) -> @builder.Node raise Abort {
  match argument {
    Producer(name) => {
      let input = resolve_relation_input([name], known)
      // This first connection consumes earlier WITH producers. Installed
      // selector Sources need the existing capture/share boundary, not an
      // undeclared producer or a new acquisition path in this lowerer.
      guard input.source is StepReference else { raise Abort(UnsupportedGraph) }
      construction.text(input.name)
    }
    FieldReference(_) => raise Abort(InvalidQuery)
    TextValue(value) => construction.text(value)
    NumberValue(text) =>
      match @expression.numeric_literal(text) {
        Ok(value) => construction.add(Number(value))
        Err(issue) =>
          raise Abort(
            Expression({ issue, origin: Some(construction.generated), }),
          )
      }
    BooleanValue(value) => construction.add(Bool(value))
    NullValue => construction.add(Null)
    ParameterValue(name) =>
      construction.object([("$param", construction.parameter_text(name))])
    ObjectValue(fields) =>
      construction.object(
        fields.map(field => {
          (
            field.0,
            script_traversal_argument(construction, field.1, known, limits),
          )
        }),
      )
    ListValue(items) =>
      construction.array(
        items.map(item => {
          script_traversal_argument(construction, item, known, limits)
        }),
      )
  }
}

///|
fn lower_script_traversal_rows(
  construction : Construction,
  query : @query.Query,
  call : @query.SgaCall,
  graph : String,
  known : Array[Input],
  limits : Limits,
  steps : Array[@builder.Node],
  reserved : Array[String],
) -> Input raise Abort {
  // Node and path emissions have different contracts. Do not borrow one
  // output schema for the other or replace an authored emission/default.
  let emissions = call.arguments.filter(argument => argument.0 == "emit")
  let fields = if call.operation == "reach" {
    ["start_id", "node_id", "depth"]
  } else if call.operation == "shortest_path" {
    [
      "source_id", "target_id", "total_cost", "hop_count", "node_ids", "edge_ids",
    ]
  } else {
    guard emissions.length() == 1 else { raise Abort(UnsupportedGraph) }
    match emissions[0].1 {
      @query.TextValue("nodes") => ["start_id", "node_id", "depth"]
      @query.TextValue("paths") =>
        ["start_id", "end_id", "hop_count", "node_ids", "edge_ids"]
      _ => raise Abort(UnsupportedGraph)
    }
  }
  let origin = match
    @origin.range(@query.query_document(query), call.start, call.end) {
    Ok(origin) => origin
    Err(_) => raise Abort(InvalidContext)
  }
  let construction = { ..construction, generated: origin, }
  let body = construction.object(
    call.arguments.map(argument => {
      (
        argument.0,
        script_traversal_argument(construction, argument.1, known, limits),
      )
    }),
  )
  let output = pipe_physical_name(reserved, "aql_sga_")
  reserved.push(output)
  steps.push(
    construction.object([
      ("from", construction.text(graph)),
      (call.operation, body),
      ("as", construction.text(output)),
    ]),
  )
  {
    relation: @query.relation(query),
    name: output,
    source: StepReference,
    visible_fields: fields,
    graph_bindings: [],
  }
}

///|
// The authored field list supplies names only. Definition/label scope, typed
// identity bindings, property presence, predicate typing and output contracts
// remain with the common Graph match checker.
fn lower_script_graph_match_rows(
  construction : Construction,
  query : @query.Query,
  call : @query.SgaCall,
  graph : String,
  known : Array[Input],
  limits : Limits,
  steps : Array[@builder.Node],
  reserved : Array[String],
) -> Input raise Abort {
  let mut fields : Array[String]? = None
  for (name, argument) in call.arguments {
    if name == "fields" {
      guard argument is ListValue(selected) && !selected.is_empty() else {
        raise Abort(UnsupportedGraph)
      }
      let names = []
      for field in selected {
        guard field is TextValue(name) else { raise Abort(UnsupportedGraph) }
        names.push(name)
      }
      fields = Some(names)
    }
  }
  guard fields is Some(visible_fields) else { raise Abort(UnsupportedGraph) }
  let origin = match
    @origin.range(@query.query_document(query), call.start, call.end) {
    Ok(origin) => origin
    Err(_) => raise Abort(InvalidContext)
  }
  let construction = { ..construction, generated: origin, }
  // Reuse the shared argument builder. Structured predicates stay expression
  // trees, and STRING values stay values; the Frontend does not parse another
  // expression dialect or infer a producer from string contents.
  let body = construction.object(
    call.arguments.map(argument => {
      (
        argument.0,
        script_traversal_argument(construction, argument.1, known, limits),
      )
    }),
  )
  let output = pipe_physical_name(reserved, "aql_sga_")
  reserved.push(output)
  steps.push(
    construction.object([
      ("from", construction.text(graph)),
      (call.operation, body),
      ("as", construction.text(output)),
    ]),
  )
  {
    relation: @query.relation(query),
    name: output,
    source: StepReference,
    visible_fields,
    graph_bindings: [],
  }
}

(* GoogleSQL-derived ActQL query surface. Semantic restrictions are in
   docs/spec/query-text.md. This grammar does not define GoogleSQL as a whole. *)
script        = query ;
query         = ( table_create_statement
              | [ with_clause ], ( sql_query | pipe_query ) ), [ ";" ] ;
(* Authored WITH bodies and ordinary parentheses are Pure. The common checker
   determines Relation/Graph/Vectors/Events; syntax does not issue a Carrier.
   Only the whole CTAS input wrapper is Compute. The public SQL selector keeps
   SELECT/WITH/CREATE/grouped SQL heads; AQL-text also admits FROM-headed Pipe. *)
table_create_statement = table_create, "AS", table_input_query ;
(* A Table input can include statement-level inference, but not another
   terminal write. Authored WITH bodies remain Pure declaration bodies. *)
table_input_query = [ with_clause ], ( sql_query | pipe_query )
                  | "(", [ with_clause ], ( sql_query | pipe_query ), ")" ;
(* The pure constructor wrapper is an ActQL extension. Its table mapping
   follows the selected GoogleSQL/SQL-PGQ profile, not ISO GQL CREATE. *)
graph_constructor = "GRAPH", "(",
                   "NODE", "TABLES", "(", node_definition,
                     { ",", node_definition }, ")",
                   [ "EDGE", "TABLES", "(", edge_definition,
                     { ",", edge_definition }, ")" ], ")" ;
node_definition = path, [ "AS", identifier ], "KEY", key_columns,
                  [ element_labels ] ;
edge_definition = path, [ "AS", identifier ], "KEY", key_columns,
                  "SOURCE", "KEY", key_columns, "REFERENCES", identifier,
                    [ key_columns ],
                  "DESTINATION", "KEY", key_columns, "REFERENCES", identifier,
                    [ key_columns ], [ element_labels ] ;
key_columns   = "(", identifier, { ",", identifier }, ")" ;
element_labels = property_selection | label_clause, { label_clause } ;
label_clause  = ( "LABEL", identifier | "DEFAULT", "LABEL" ),
                [ property_selection ] ;
property_selection = "NO", "PROPERTIES"
                   | "PROPERTIES", [ "ARE" ],
                     ( "ALL", "COLUMNS", [ "EXCEPT", key_columns ]
                     | "(", property_column, { ",", property_column }, ")" ) ;
property_column = identifier, [ "AS", identifier ] ;
sql_query     = sql_operand, { set_part },
                [ order_clause ], [ limit_clause ], { "|>", pipe_item } ;
with_clause   = "WITH", with_binding, { ",", with_binding } ;
with_binding  = identifier, "AS", "(", producer_body, ")" ;
producer_body = [ with_clause ],
                ( relational_sql | cte_pipe | producer_primary, { "|>", cte_pipe_item } ) ;
producer_primary = graph_constructor | graph_generator ;
graph_generator = "mean_graphs", "(", [ sga_argument, { ",", sga_argument } ], ")" ;
(* Primaries construct Graph values. Existing Vectors/Events are reached
   through typed named Pipe calls, without changing the common value wire. *)
relational_body = producer_body ;
(* Derived tables and set operands require a Relation after static checking. *)
relational_sql = sql_operand, { set_part }, [ order_clause ], [ limit_clause ],
                 { "|>", cte_pipe_item } ;
sql_operand   = select_core | "(", relational_body, ")" ;
(* Declaration bodies exclude statement-level INFER, RESULT and EFFECT declarations. *)
cte_pipe      = "FROM", carrier_source, { "|>", cte_pipe_item } ;
cte_pipe_item = relation_pipe_item | nearest_operator | named_sga_call | graph_match ;
select_core   = "SELECT", [ "DISTINCT" ], select_list, [ "FROM", source, { join } ],
                [ where_clause ], [ group_clause ],
                [ having_clause ], [ qualify_clause ], [ window_clause ] ;
pipe_query    = "FROM", carrier_source, { "|>", pipe_item } ;
carrier_source = source | "GRAPH", path, [ source_alias ] ;
(* FROM preserves the resolved Carrier. GRAPH adds an explicit Graph type
   expectation; MATCH does not require the marker. An authored row alias
   requires Relation and never renames Graph element definitions. *)
graph_match   = "MATCH", [ identifier, "=" ],
                [ "WALK" | "TRAIL" | "ACYCLIC" ],
                graph_node, { graph_edge, graph_node } ;
graph_node    = "(", [ identifier ], [ ":", identifier ],
                [ graph_constraint ], ")" ;
graph_edge    = ( "-[", graph_filler, "]->"
                | "<-[", graph_filler, "]-"
                | "-[", graph_filler, "]-"
                | "-" | "<-" | "->" ),
                [ graph_quantifier ] ;
graph_filler  = [ identifier ], [ ":", identifier ],
                [ graph_constraint ] ;
graph_constraint = "WHERE", expression
                | "{", property_pair, { ",", property_pair }, "}" ;
property_pair = identifier, ":", expression ;
graph_quantifier = "{", integer, "}"
                 | "{", [ integer ], ",", integer, "}" ;
source        = table_source | unnest_source ;
table_source  = path, [ source_alias ], [ pivot_operator | unpivot_operator ]
              | "(", relational_body, ")",
                [ source_alias ], [ pivot_operator | unpivot_operator ] ;
source_alias  = [ "AS" ], identifier ;
unnest_source = "UNNEST", "(", expression, ")", source_alias,
                [ "WITH", "OFFSET", [ source_alias ] ] ;
join          = [ "INNER" | "LEFT", [ "OUTER" ]
                | "RIGHT", [ "OUTER" ]
                | "FULL", [ "OUTER" ] ],
                "JOIN", table_source, ( "ON", expression
                | "USING", "(", identifier, { ",", identifier }, ")" ),
                [ join_bound ]
              | "CROSS", "JOIN", table_source, [ join_bound ]
              | "CROSS", "JOIN", unnest_source
              | [ "INNER" ], "JOIN", unnest_source, [ "ON", expression ] ;
join_bound    = "MAX_OUTPUT_ROWS", integer ;
where_clause  = "WHERE", expression ;
group_clause  = "GROUP", "BY", ( "ALL" | "(", ")" | expression, { ",", expression } ) ;
pipe_group_clause = "GROUP", [ "AND", "ORDER" ], "BY", ( "(", ")" | pipe_group_item, { ",", pipe_group_item } ) ;
pipe_group_item = expression, [ [ "AS" ], identifier ], [ pipe_group_order ] ;
pipe_group_order = [ "ASC" | "DESC" ], "NULLS", ( "FIRST" | "LAST" )
                 | "ASC" | "DESC" ;
pipe_aggregate_list = pipe_aggregate_item, { ",", pipe_aggregate_item } ;
pipe_aggregate_item = expression, [ [ "AS" ], identifier ], [ pipe_aggregate_order ] ;
pipe_aggregate_order = ( "ASC" | "DESC" ), [ "NULLS", ( "FIRST" | "LAST" ) ] ;
having_clause = "HAVING", expression ;
qualify_clause = "QUALIFY", expression ;
window_clause = "WINDOW", window_definition, { ",", window_definition } ;
window_definition = identifier, "AS", window_specification ;
window_specification = identifier
                     | "(", [ identifier ], [ partition_clause ],
                       [ order_clause ], [ rows_frame ], ")" ;
partition_clause = "PARTITION", "BY", expression, { ",", expression } ;
rows_frame = "ROWS", ( "BETWEEN", frame_boundary, "AND", frame_boundary
                     | frame_boundary ) ;
frame_boundary = "CURRENT", "ROW"
               | "UNBOUNDED", ( "PRECEDING" | "FOLLOWING" )
               | limit_integer, ( "PRECEDING" | "FOLLOWING" ) ;
select_list   = select_item, { ",", select_item } ;
select_item   = ( "*" | expression, ".", "*" ), [ star_except ], [ star_replace ]
              | expression, [ "AS", identifier ] ;
star_except   = "EXCEPT", "(", identifier, { ",", identifier }, ")" ;
star_replace  = "REPLACE", "(", expression, "AS", identifier,
               { ",", expression, "AS", identifier }, ")" ;
order_clause  = "ORDER", "BY", sort_item, { ",", sort_item } ;
sort_item     = expression, [ "ASC" | "DESC" ],
                [ "NULLS", ( "FIRST" | "LAST" ) ] ;
limit_clause  = "LIMIT", limit_integer, [ "OFFSET", limit_integer ] ;
limit_integer = integer | parameter_token | "+", limit_integer
              | "(", limit_integer, ")" ;
set_operator  = "UNION", ( "ALL" | "DISTINCT" )
              | "INTERSECT", "DISTINCT" | "EXCEPT", "DISTINCT" ;
set_names     = "BY", "NAME", [ "ON", "(", identifier, { ",", identifier }, ")" ]
              | [ "STRICT" ], "CORRESPONDING", [ "BY", "(", identifier, { ",", identifier }, ")" ] ;
set_matching  = set_operator, [ set_names ]
              | "INNER", set_operator,
                ( "BY", "NAME", [ "ON", "(", identifier, { ",", identifier }, ")" ]
                | "CORRESPONDING", [ "BY", "(", identifier, { ",", identifier }, ")" ] ) ;
set_part      = set_matching, sql_operand ;
pipe_item     = relation_pipe_item | infer_operator | nearest_operator
              | result_operator | terminal_effect | named_sga_call | graph_match ;
(* Named SGA calls are ActQL extensions for existing logical Graph operators.
   Carrier transitions and implemented consumers are checked separately. *)
named_sga_call = sga_operation, "(",
                 [ sga_argument, { ",", sga_argument } ], ")" ;
sga_operation = "reach" | "traverse" | "shortest_path" | "components"
              | "degree" | "graph_bounds" | "match_nodes" | "match_edges"
              | "normalize_graph" | "subgraph" | "graft_graph"
              | "union_graphs" | "subtract_graphs" | "graphs_equal"
              | "graph_diff" | "apply_graph_delta" | "mean_graphs"
              | "node_rows" | "edge_rows"
              | "to_vectors" | "normalize_vectors" | "score_vectors" | "vectors"
              | "to_events" | "session" | "events" ;
sga_argument  = identifier, ":", sga_value ;
sga_value     = query_string | [ "-" ], numeric_token | "TRUE" | "FALSE"
              | "NULL" | parameter_token
              | path (* only an operation-defined producer or field-reference position *)
              | "{", [ sga_argument, { ",", sga_argument } ], "}"
              | "[", [ sga_value, { ",", sga_value } ], "]" ;
result_operator = "RESULT", identifier ;
assertion_operator = "ASSERT", "UNIQUE", "BY", "(", path, { ",", path }, ")" ;
terminal_effect = terminal_update | [ "EFFECT", identifier ], table_create ;
table_create  = "CREATE", [ "OR", "REPLACE" ], "TABLE", path ;
terminal_update = "EFFECT", identifier, "UPDATE", "TARGET", query_string,
                  "MAPPING", identifier, "FROM", "RESULT", identifier,
                  "ID", identifier, "SET", "(", assignment, { ",", assignment }, ")" ;
(* Pipe WHERE permits supported inline window calls in its predicate. *)
pipe_where_clause = "WHERE", expression ;
(* Pipe SET permits supported inline window calls in assignment expressions. *)
pipe_set_clause = "SET", assignment, { ",", assignment } ;
relation_pipe_item = assertion_operator | pipe_where_clause | "DISTINCT" | "SELECT", [ "DISTINCT" ], select_list, [ window_clause ]
              | "EXTEND", select_list, [ window_clause ]
              | pipe_set_clause
              | unpivot_operator
              | "DROP", identifier, { ",", identifier }
              | "RENAME", rename, { ",", rename }
              | "AS", identifier
              | pivot_operator
              | "AGGREGATE", ( pipe_aggregate_list, [ pipe_group_clause ] | pipe_group_clause )
              | join | order_clause | limit_clause
              | pipe_set_part ;
(* Pipe PIVOT: one scalar-argument aggregate or COUNT star and static String buckets. *)
pivot_operator = "PIVOT", "(", pivot_call,
                 [ [ "AS" ], identifier ], "FOR", path, "IN", "(",
                 pivot_value, { ",", pivot_value }, ")", ")",
                 [ [ "AS" ], identifier ] ;
pivot_call = pivot_aggregate, "(", expression, ")" | "COUNT", "(", "*", ")" ;
pivot_aggregate = "SUM" | "AVG" | "COUNT" | "MIN" | "MAX" ;
pivot_value = pivot_string, [ [ "AS" ], identifier ] ;
pivot_string = query_string | "(", pivot_string, ")" ;
unpivot_operator = "UNPIVOT", [ ( "INCLUDE" | "EXCLUDE" ), "NULLS" ],
                   "(", unpivot_column_set, "FOR", identifier, "IN", "(",
                   unpivot_input, { ",", unpivot_input }, ")", ")", [ source_alias ] ;
unpivot_column_set = identifier | "(", identifier, { ",", identifier }, ")" ;
unpivot_input = unpivot_column_set, [ [ "AS" ], ( query_string | integer ) ] ;
infer_operator = "INFER", identifier, "ITEM", "KEY", "(",
                 path, { ",", path }, ")", "INPUT", "(",
                 [ assignment, { ",", assignment } ], ")",
                 [ keep_clause ], "AS", identifier ;
nearest_operator = "NEAREST", path, "AS", identifier,
                   "QUERY", "KEY", "(", path, { ",", path }, ")",
                   "VECTOR", expression,
                   "CANDIDATE", "KEY", "(", path, { ",", path }, ")",
                   "VECTOR", expression, "METRIC", metric,
                   "K", integer, [ keep_clause ], "AS", identifier ;
metric        = "cosine" | "dot" | "l2" ;
keep_clause   = "KEEP", "(", keep_item, { ",", keep_item }, ")" ;
keep_item     = path, [ "AS", identifier ] | "*" | path, ".", "*" ;
pipe_set_part = set_matching, "(", relational_body, ")" ;
assignment    = identifier, "=", expression ;
rename        = identifier, "AS", identifier ;
path          = identifier, { ".", identifier } ;
expression    = ? closed query expression grammar in query-text.md ? ;
array_constructor = [ "ARRAY", [ "<", array_item_type, ">" ] ],
                    "[", [ expression, { ",", expression } ], "]" ;
array_item_type = "BOOL" | "BOOLEAN" | "STRING" | "FLOAT64" | "DOUBLE"
                | "TIMESTAMP" | "JSON" ;
(* ARRAY annotations and compatible item types use the common checker.
   JSON constructors/default INT64 remain common-contract coverage gaps. *)
identifier    = ? ASCII identifier or backtick-quoted identifier ? ;
integer       = ? unsigned decimal or 0x/0X hexadecimal integer within the adopted exact range; context-specific positivity and role checks apply ? ;
numeric_token = ? decimal numeric token or 0x/0X hexadecimal integer token; raw spelling is retained and exact admission is separate ? ;
parameter_token = ? existing query named parameter token ? ;
query_string  = ? one or more whitespace/comment-separated single-, double- or triple-quoted Unicode scalar string chunks, with per-chunk optional r/R raw prefix and the selected GoogleSQL decoding rules in query-text.md; decoded octal escapes use exactly three digits with first digit 0..3 (maximum \377) ? ;
